/* DSM order and KPI revisions. Loaded after the existing Telemarketing module. */
tmOrdersTable=function(orders){return table(['Nomor / Tanggal','Dealer','Sales person','Region / Refnote','Status','Dokumen'],orders.map(o=>[esc(o.number)+'<small class="cellsub">'+tgl(o.date)+'</small>',esc(o.dealerSnapshot?.name)+(o.dealerMode==='manual'?' <b>NOO</b>':''),esc(o.sales),esc(o.region)+'<small class="cellsub">'+esc(o.refnote||'—')+'</small>',esc(o.status),`<button class="chip" data-tm-preview="${esc(o.id)}">PDF / Teks</button> <button class="chip" data-tm-editorder="${esc(o.id)}">Edit</button>`]));};
function tmMoneyNum(v){if(v===null||v==='')return 0;const s=String(v).trim().replace(/\s/g,'');return Number(/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)?s.replace(/\./g,'').replace(',','.'):s.replace(',','.'))||0;}
tmTotals=function(o){const qty=o.items.reduce((n,i)=>n+(Number(i.qty)||0),0),amount=o.items.reduce((n,i)=>n+(Number(i.qty)||0)*tmMoneyNum(i.price),0),credit=Number(o.creditNote)||0,discount=o.creditMode==='PERCENT'?amount*credit/100:credit;return {qty,amount,discount,total:Math.max(0,amount-discount),complete:o.items.every(i=>i.price!==''&&i.price!==null)};};
tmDrawTotals=function(){const o=tmState.order,t=tmTotals(o),el=$('tmOrderTotal');if(!el)return;el.innerHTML=`<div><span>Subtotal</span><b>${rupiah(t.amount)}</b></div><div><span>Credit Note ${o.creditMode==='PERCENT'?'('+num(o.creditNote)+'%)':''}</span><b>− ${rupiah(t.discount)}</b></div><div class="tm-grand-total"><span>Total · ${num(t.qty)} unit</span><b>${rupiah(t.total)}</b></div>`;o.items.forEach(i=>{const cell=document.querySelector(`[data-tm-subtotal=\"${i.uid}\"]`);if(cell)cell.textContent=rupiah((Number(i.qty)||0)*tmMoneyNum(i.price));});};
tmCollectOrder=function(){const o=tmState.order;if(!o)return;document.querySelectorAll('#tmOrderForm [data-tm-field]').forEach(el=>o[el.dataset.tmField]=el.type==='checkbox'?el.checked:el.value);document.querySelectorAll('#tmOrderForm [data-tm-item-field]').forEach(el=>{const i=o.items.find(x=>x.uid===el.dataset.uid);if(i)i[el.dataset.tmItemField]=el.value;});document.querySelectorAll('#tmOrderForm [data-tm-dealerfield]').forEach(el=>{if(o.dealerMode==='master')o.dealerSnapshot[el.dataset.tmDealerfield]=el.value;else o.manualDealer[el.dataset.tmDealerfield]=el.value;});if(o.dealerMode==='manual')o.dealerSnapshot={...o.manualDealer};};
tmValidateOrder=function(o){const t=tmTotals(o),message=!o.businessId?'Pilih badan usaha.':!o.dealerSnapshot?.name?'Pilih atau isi nama dealer.':!String(o.sales||'').trim()||!String(o.region||'').trim()?'Isi sales person dan region.':!o.items.length?'Tambahkan barang.':o.items.some(i=>!i.name||!i.brand||!i.color||!Number.isInteger(Number(i.qty))||Number(i.qty)<1)?'Lengkapi nama, brand, warna dan jumlah barang.':t.discount>t.amount?'Credit Note tidak boleh melebihi subtotal.':o.payment==='TOP'&&!(Number(o.topDays)>0&&Number(o.topDays)<=365)?'Isi tempo TOP 1–365 hari.':'';if(message){$('tmOrderError').textContent=message;return false;}return true;};
tmDrawOrder=function(){
 const o=tmState.order,b=tmState.boot;if(!o)return;const dealer=b.dealers.find(d=>d.id===o.dealer),snap=o.dealerMode==='master'?(o.dealerSnapshot||dealer):o.manualDealer;
 const input=(label,key,type='text')=>`<label>${label}<input class="fi" type="${type}" data-tm-field="${key}" value="${esc(o[key]??'')}"></label>`;
 $('tmOrderList').hidden=true;$('tmOrderEditor').innerHTML=`<form id="tmOrderForm"><div class="toolbar tm-sticky-actions"><button class="chip primary" type="submit">Simpan order</button><button class="chip" type="button" id="tmDraft">Simpan draft</button><button class="chip" type="button" id="tmPreview">Pratinjau PDF / teks</button><span class="hint" id="tmOrderMsg"></span></div>`+
 tmFormGroup('01','Identitas order','Badan usaha, region, refnote, jenis order',`<div class="userForm"><label>Badan usaha<select class="fi" data-tm-field="businessId" required>${tmOptions(b.businesses.map(x=>({value:x.id,label:x.name})),o.businessId)}</select></label>${input('Tanggal','date','date')}<label>Region<select class="fi" data-tm-field="region">${tmOptions([...new Set([o.region,...(b.regions||b.dealers.map(d=>d.subRegion))].filter(Boolean))],o.region)}</select></label>${input('Ref Note','refnote')}<label>Jenis order<select class="fi" data-tm-field="payment">${tmOptions([{value:'CBD',label:'CBD · Cash Before Delivery'},{value:'COD',label:'COD · Cash on Delivery'},{value:'TOP',label:'TOP · Term of Payment'}],o.payment||'CBD')}</select></label><label id="tmTopDays" ${o.payment==='TOP'?'':'hidden'}>Tempo TOP (hari)<input class="fi" type="number" min="1" max="365" data-tm-field="topDays" value="${esc(o.topDays||'')}"></label></div><p class="hint">${esc(o.number)} · dibuat oleh ${esc(BOOT.user.nama)}</p>`)+
 tmFormGroup('02','Dealer & penjual','Alamat dan nomor HP bisa dikoreksi untuk order ini',`<div class="toolbar"><label><input type="radio" name="tmDealerMode" value="master" ${o.dealerMode==='master'?'checked':''}> Dealer terdaftar</label><label><input type="radio" name="tmDealerMode" value="manual" ${o.dealerMode==='manual'?'checked':''}> Dealer baru · NOO</label></div>${o.dealerMode==='master'?`<label>Cari nama / kode dealer<input class="fi" list="tmDealerList" id="tmDealerFind" value="${esc(dealer?dealer.name+' · '+dealer.id:'')}" placeholder="Pilih dealer"><datalist id="tmDealerList">${b.dealers.map(d=>`<option value="${esc(d.name+' · '+d.id)}"></option><option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</datalist></label>`:'<p class="tm-noo">Dealer NOO · belum terdaftar di database DSM.</p>'}<div class="userForm">${[['Nama dealer','name'],['PIC / pemilik','owner'],['Nomor HP','phone'],['Alamat','address']].map(([label,key])=>`<label>${label}<input class="fi" data-tm-dealerfield="${key}" value="${esc(snap?.[key]||'')}" ${key==='name'&&o.dealerMode==='master'?'readonly':''}></label>`).join('')}</div><div class="tm-seller-row"><label>Sales person / penjual<input class="fi" list="tmSalesList" data-tm-field="sales" value="${esc(o.sales||'')}" placeholder="Pilih atau ketik nama"><datalist id="tmSalesList"><option value="${esc(BOOT.user.nama)}"></option>${b.sales.map(p=>`<option value="${esc(p.nama)}">${esc(p.nik)}</option>`).join('')}</datalist></label></div>`)+
 tmFormGroup('03','Barang pesanan','Satu barang satu baris · nama barang ditulis bebas',`<div class="tm-items-toolbar"><span>${o.items.length} baris barang</span><button class="chip" type="button" id="tmItemAdd">+ Baris baru <kbd>F7</kbd></button></div><div class="table-scroll tm-order-scroll"><table class="tm-order-table"><thead><tr><th>No</th><th>Brand</th><th>Nama barang / TYPE</th><th>Warna</th><th>Qty</th><th>Harga</th><th>Subtotal</th><th></th></tr></thead><tbody>${o.items.map((i,n)=>`<tr><td>${n+1}</td><td><input class="fi" list="tmBrandList" data-tm-item-field="brand" data-uid="${esc(i.uid)}" value="${esc(i.brand)}" placeholder="Pilih / baru"></td><td><input class="fi" data-tm-item-field="name" data-uid="${esc(i.uid)}" value="${esc(i.name)}" placeholder="Nama barang manual"></td><td><input class="fi" list="tmColors" data-tm-item-field="color" data-uid="${esc(i.uid)}" value="${esc(i.color)}"></td><td><input class="fi" type="number" min="1" step="1" data-tm-item-field="qty" data-uid="${esc(i.uid)}" value="${esc(i.qty)}"></td><td><input class="fi" inputmode="decimal" data-tm-item-field="price" data-uid="${esc(i.uid)}" value="${esc(i.price)}"></td><td><span data-tm-subtotal="${esc(i.uid)}">${rupiah((Number(i.qty)||0)*tmMoneyNum(i.price))}</span></td><td><button class="chip" type="button" data-tm-remove="${esc(i.uid)}" aria-label="Hapus barang ${n+1}">✕</button></td></tr>`).join('')}</tbody></table></div><datalist id="tmBrandList">${(b.brands||[]).map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist><datalist id="tmColors">${['Hitam','Putih','Merah','Biru','Hijau','Emas'].map(v=>`<option value="${v}"></option>`).join('')}</datalist><div class="tm-summary"><div class="tm-credit"><label>Credit Note · potongan order<select class="fi" data-tm-field="creditMode">${tmOptions([{value:'NOMINAL',label:'Nominal Rp'},{value:'PERCENT',label:'Persen %'}],o.creditMode||'NOMINAL')}</select></label>${input('Nilai Credit Note','creditNote')}</div><div id="tmOrderTotal"></div></div>`)+
 tmFormGroup('04','Catatan & dokumen','Order internal, tidak mengubah transaksi atau KPI',`<label>Catatan<textarea class="fi" data-tm-field="notes" maxlength="4000" rows="3">${esc(o.notes||'')}</textarea></label><label class="confirm"><input type="checkbox" data-tm-field="showPrice" ${o.showPrice?'checked':''}> Cantumkan harga di PDF</label><p class="hint" id="tmOrderError" role="alert"></p>`)+`</form>`;
 const form=$('tmOrderForm');form.querySelectorAll('[data-tm-field]').forEach(el=>el.onchange=()=>{tmCollectOrder();if(el.dataset.tmField==='businessId'){const bu=b.businesses.find(x=>x.id===o.businessId);o.businessSnapshot=bu;o.company=bu?.name||'';}if(el.dataset.tmField==='payment')$('tmTopDays').hidden=o.payment!=='TOP';tmDrawTotals();});
 form.querySelectorAll('[name=tmDealerMode]').forEach(el=>el.onchange=()=>{tmCollectOrder();o.dealerMode=el.value;if(el.value==='manual'){o.dealer='';o.dealerSnapshot={...o.manualDealer};}tmDrawOrder();});
 $('tmDealerFind')?.addEventListener('change',e=>{const raw=e.target.value,hit=b.dealers.find(x=>x.id===raw||x.name+' · '+x.id===raw);if(!hit){$('tmOrderError').textContent='Pilih dealer dari daftar.';return;}tmCollectOrder();o.dealer=hit.id;o.dealerSnapshot={id:hit.id,name:hit.name,owner:hit.owner,phone:hit.phone,address:hit.address};o.sales=BOOT.user.role==='SALES'?BOOT.user.nama:(hit.sales||BOOT.user.nama);o.region=hit.subRegion||o.region;tmDrawOrder();});
 form.querySelectorAll('[data-tm-dealerfield],[data-tm-item-field]').forEach(el=>el.oninput=()=>{tmCollectOrder();tmDrawTotals();});
 form.querySelectorAll('[data-tm-remove]').forEach(el=>el.onclick=()=>{tmCollectOrder();o.items=o.items.filter(x=>x.uid!==el.dataset.tmRemove);tmDrawOrder();});
 $('tmItemAdd').onclick=()=>{tmCollectOrder();o.items.push(tmEmptyItem());tmDrawOrder();};$('tmPreview').onclick=()=>{tmCollectOrder();if(tmValidateOrder(o))tmPreviewOrder(o);};$('tmDraft').onclick=()=>tmSaveOrder('DRAFT');form.onsubmit=e=>{e.preventDefault();tmSaveOrder('SAVED');};tmDrawTotals();
};
var tmDrawOrderStack=tmDrawOrder;
function tmOrderText(o){const d=o.dealerSnapshot||o.manualDealer||{},t=tmTotals(o),m=n=>'Rp. '+new Intl.NumberFormat('id-ID').format(Number(n)||0),date=new Date(o.date+'T12:00:00Z').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});return [`==================`,o.company||o.businessSnapshot?.name||'BADAN USAHA',`==================`,'',`Dealer : ${o.dealerMode==='manual'?'DEALER NOO · ':''}${d.id?d.id+' - ':''}${d.name||'-'}`,`Alamat : ${d.address||'-'}`,`No. HP : ${d.phone||'-'}`,'',`Sales Person : ${o.sales||'-'}`,`Tanggal : ${date}`,`Region : ${o.region||'-'}`,`Ref Note : ${o.refnote||'-'}`,`Jenis Order : ${o.payment||'CBD'}${o.payment==='TOP'?' · '+o.topDays+' hari':''}`,`Catatan : ${o.notes||'-'}`,'','DETAIL BARANG :','============================',...o.items.map((i,n)=>`${n+1}. ${i.brand} - ${i.name} - ${i.color} : ${i.qty} unit - ${m(i.price)} > ${m(Number(i.qty)*Number(i.price))}`),'',`Subtotal : ${m(t.amount)}`,`Credit Note${o.creditMode==='PERCENT'?' ('+o.creditNote+'%)':''} : ${m(t.discount)}`,'====================',`TOTAL : ${m(t.total)}`].join('\n');}
tmPreviewOrder=function(o){if(!o)return;const snapshot=structuredClone(o);snapshot.items.forEach(i=>{if(i.price!=='')i.price=tmMoneyNum(i.price)});const pages=DSMTMPdf.layout(snapshot),txt=tmOrderText(snapshot);modal('Order · '+snapshot.number,`<div class="toolbar tm-sticky-actions"><button class="chip primary" id="tmPdfDownload">Download PDF</button><button class="chip" id="tmTextCopy">Salin teks WA</button><button class="chip" id="tmTextDownload">Download .txt</button></div><details><summary>Format teks untuk grup WhatsApp</summary><pre class="tm-wa-text">${esc(txt)}</pre></details><div class="tm-pdf-preview">${DSMTMPdf.svg(pages)}</div>`);$('tmPdfDownload').onclick=()=>{const blob=new Blob([DSMTMPdf.pdf(pages)],{type:'application/pdf'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(snapshot.number.startsWith('Nomor otomatis')?'Catatan_Order':snapshot.number)+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('tmTextCopy').onclick=()=>{if(navigator.clipboard?.writeText)navigator.clipboard.writeText(txt).then(()=>$('tmTextCopy').textContent='Tersalin ✓').catch(()=>{});else tfaCopyOld(txt,()=>$('tmTextCopy').textContent='Tersalin ✓');};$('tmTextDownload').onclick=()=>{const url=URL.createObjectURL(new Blob([txt],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=(snapshot.number.startsWith('Nomor otomatis')?'Catatan_Order':snapshot.number)+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};};
document.addEventListener('keydown',e=>{if(e.key==='F7'&&PAGE==='tmorder'&&$('tmItemAdd')){e.preventDefault();$('tmItemAdd').click();}});

/* Assignment is entered per region × brand, with explicit Sales and dealer scope. */
tmAssignmentEditor=function(p,a){
 const regions=[...new Set(a.sales.map(x=>x.wilayah).filter(Boolean))].sort(),old=p.pairs||[];
 let groups=old.length?Object.values(old.reduce((map,pair)=>{const s=a.sales.find(x=>x.nik===pair.sales_nik),region=s?.wilayah||'';if(!region)return map;const key=region+'\u001f'+pair.brand,entry=map[key]||(map[key]={region,brand:pair.brand,sales:[],mode:'SELECTED',dealers:[]});if(!entry.sales.includes(pair.sales_nik))entry.sales.push(pair.sales_nik);entry.dealers.push(pair.dealer);return map;},{})):[{region:regions[0]||'',brand:a.brands[0]||'',sales:[],mode:'ALL',dealers:[]}];
 let reason='',correct=false;
 const container=()=>document.getElementById('tmAssignmentForm');
 const draw=()=>{modal('Penugasan · '+p.nama,`<form id="tmAssignmentForm"><p class="hint">Setiap kelompok memilih region, Sales, brand, lalu semua dealer Sales atau dealer tertentu. Brand yang sama pada dealer yang sama hanya boleh dimiliki satu Telemarketing.</p><div id="tmAssignGroups">${groups.map((g,n)=>`<section class="tm-assign-group"><div class="toolbar"><b>Kelompok ${n+1}</b><button class="chip" type="button" data-assign-remove="${n}">Hapus</button></div><div class="userForm"><label>Region<select class="fi" data-assign-region="${n}">${tmOptions(regions,g.region)}</select></label><label>Brand<select class="fi" data-assign-brand="${n}">${tmOptions(a.brands,g.brand)}</select></label><label>Cakupan dealer<select class="fi" data-assign-mode="${n}">${tmOptions([{value:'ALL',label:'Semua dealer Sales terpilih'},{value:'SELECTED',label:'Dealer pilihan'}],g.mode)}</select></label></div><details open><summary>Sales terpilih · ${g.sales.length} orang</summary><div class="tm-scroll-list regionChecks">${a.sales.filter(s=>s.wilayah===g.region).map(s=>`<label><input type="checkbox" data-assign-sales="${n}" value="${esc(s.nik)}" ${g.sales.includes(s.nik)?'checked':''}> ${esc(s.nama)} · ${esc(s.portfolio||s.region||'')}</label>`).join('')||'<p class="hint">Belum ada Sales di wilayah ini.</p>'}</div></details>${g.mode==='SELECTED'?`<details open><summary>Dealer pilihan · ${g.dealers.length}</summary><label>Cari dealer<input class="fi" data-assign-search="${n}" placeholder="Nama / kode dealer"></label><div class="tm-scroll-list" id="tmAssignDealers${n}"></div></details>`:''}</section>`).join('')}</div><div class="toolbar"><button class="chip" type="button" id="tmAssignAdd">+ Kelompok wilayah–brand</button></div><label class="confirm"><input type="checkbox" id="tmAssignCorrect" ${correct?'checked':''}> Koreksi cakupan KPI bulan berjalan</label><p class="hint">Perubahan akses dealer berlaku langsung; KPI mengikuti periode efektif. Histori lama tetap tersimpan.</p><label>Alasan perubahan<input class="fi" id="tmAssignReason" value="${esc(reason)}" minlength="5" required></label><p id="tmAssignError" role="alert"></p><button class="chip primary">Simpan penugasan</button></form>`);
  const f=container(),rerender=()=>{reason=$('tmAssignReason').value;correct=$('tmAssignCorrect').checked;draw();};
  f.querySelectorAll('[data-assign-region]').forEach(el=>el.onchange=()=>{groups[+el.dataset.assignRegion].region=el.value;groups[+el.dataset.assignRegion].sales=[];groups[+el.dataset.assignRegion].dealers=[];rerender();});
  f.querySelectorAll('[data-assign-brand]').forEach(el=>el.onchange=()=>{groups[+el.dataset.assignBrand].brand=el.value;groups[+el.dataset.assignBrand].dealers=[];rerender();});
  f.querySelectorAll('[data-assign-mode]').forEach(el=>el.onchange=()=>{groups[+el.dataset.assignMode].mode=el.value;rerender();});
  f.querySelectorAll('[data-assign-sales]').forEach(el=>el.onchange=()=>{const g=groups[+el.dataset.assignSales];g.sales=[...f.querySelectorAll(`[data-assign-sales="${el.dataset.assignSales}"]:checked`)].map(x=>x.value);g.dealers=[];rerender();});
  f.querySelectorAll('[data-assign-remove]').forEach(el=>el.onclick=()=>{groups.splice(+el.dataset.assignRemove,1);rerender();});
  const dealerRows=n=>{const g=groups[n],box=$('tmAssignDealers'+n);if(!box)return;const query=f.querySelector(`[data-assign-search="${n}"]`).value.toLowerCase().trim(),rows=a.dealers.filter(d=>d.bigRegion===g.region&&g.sales.includes(d.salesByBrand?.[g.brand]||d.sales_nik)&&(d.dealer+' '+d.nama+' '+d.sales).toLowerCase().includes(query));box.innerHTML=rows.slice(0,250).map(d=>`<label class="tm-assignment-row"><input type="checkbox" data-assign-dealer="${n}" value="${esc(d.dealer)}" ${g.dealers.includes(d.dealer)?'checked':''}><span><b>${esc(d.nama)}</b><small>${esc(d.dealer+' · '+d.sales)}</small></span></label>`).join('')+`<p class="hint">Menampilkan ${Math.min(rows.length,250)} dari ${rows.length} dealer. Cari untuk mempersempit.</p>`;box.querySelectorAll('[data-assign-dealer]').forEach(el=>el.onchange=()=>{g.dealers=el.checked?[...new Set([...g.dealers,el.value])]:g.dealers.filter(d=>d!==el.value);});};
  f.querySelectorAll('[data-assign-search]').forEach(el=>{el.oninput=()=>dealerRows(+el.dataset.assignSearch);dealerRows(+el.dataset.assignSearch);});
  $('tmAssignAdd').onclick=()=>{groups.push({region:regions[0]||'',brand:a.brands[0]||'',sales:[],mode:'ALL',dealers:[]});rerender();};
  f.onsubmit=async e=>{e.preventDefault();reason=$('tmAssignReason').value.trim();correct=$('tmAssignCorrect').checked;const button=f.querySelector('button[type=submit],button.chip.primary');button.disabled=true;try{if(!groups.length||groups.some(g=>!g.region||!g.brand||!g.sales.length||g.mode==='SELECTED'&&!g.dealers.length))throw Error('Lengkapi region, brand, Sales, serta dealer pilihan setiap kelompok.');const result=await rpc('apiTMAssignmentSave',TOKEN,p.nik,{revision:p.profile.revision,mode:'MIXED',groups,reason,correctCurrent:correct});closeModal();tmAdminDraw(await tmAdminLoad());modal('Penugasan tersimpan',`<p>${result.pairs.length} pasangan dealer–brand. Cakupan KPI berlaku mulai <b>${esc(bulan(result.effectivePeriod))}</b>.</p>`);}catch(err){$('tmAssignError').textContent=err.message;}finally{button.disabled=false;}};
 };draw();
};

/* Telemarketing KPI follows the Sales row editor, including brand-scoped TYPE popovers. */
tmKpiEditor=async function(p,period,a){
 let cfg=await rpc('apiTMKpiSettings',TOKEN,p.nik,period);
 let rows=structuredClone(cfg.indicators.length?cfg.indicators:[tmDefaultIndicator()]),reason='';
 const allBrands=['ALL',...a.brands],typesByBrand=a.typesByBrand||{},allTypes=a.types||[];
 const metrics=[{value:'QTY',label:'Sell Thru'},{value:'DA',label:'Dealer Aktif'},{value:'NOO',label:'NOO'},{value:'IDDLE',label:'Dealer IDDLE'},{value:'OMZET',label:'Omzet'},{value:'MANUAL',label:'KPI khusus'}];
 const numeric=['weight','cap','target','actual','minQty','perProm'];
 let groups=[...new Set(['KPI ALL BRAND',...a.brands.map(b=>'KPI '+b),...rows.map(r=>r.group)])];
 const normalize=r=>{r.types||=[];r.requirements||=[];r.minQty??=r.metric==='DA'?2:1;r.source||='AUTO';r.cap??=100;r.perProm??=3;r.group||='KPI ALL BRAND';r.variant||='BASIC';r.scopeMode||='PAIR';r.scopeDealers||=[];r.scopeDealersText=r.scopeDealers.join(', ');return r;};
 rows.forEach(normalize);
 const typeList=brand=>(brand==='ALL'?allTypes:(typesByBrand[brand]||typesByBrand[Object.keys(typesByBrand).find(k=>k.toUpperCase()===String(brand).toUpperCase())]||[])).slice().sort((x,y)=>x.localeCompare(y));
 const field=(k,n)=>`data-kpi-field="${k}" data-row="${n}"`;
 const input=(k,n,r,klass='')=>`<input class="fi ${klass}" ${field(k,n)} value="${esc(r[k]??'')}" ${numeric.includes(k)?'inputmode="decimal"':''}>`;
 const typeName=list=>list.length?(list.length<=2?list.map(esc).join(' · '):esc(list[0])+' +'+(list.length-1)):'<span class="hint">semua type</span>';
 const read=()=>{const root=$('tmSettingsBox');if(!root)return;for(const el of root.querySelectorAll('[data-kpi-field]')){const row=rows[+el.dataset.row],key=el.dataset.kpiField,value=el.type==='checkbox'?el.checked:el.value;row[key]=numeric.includes(key)?(value===''?null:Number(targetInputNumber(value))):value;}rows.forEach(r=>{r.scopeDealers=r.scopeMode==='DEALERS'?String(r.scopeDealersText||'').split(/[,\s;]+/).map(x=>x.trim()).filter(Boolean):[];});reason=$('tmKpiReason')?.value||reason;};
 const closeTypes=()=>document.querySelectorAll('.tm-kpi-type-pop').forEach(pop=>pop.remove());
 const draw=()=>{
  const root=$('tmSettingsBox');if(!root)return;
  const scroller=root.querySelector('.tm-kpi-grid'),scrollX=scroller?.scrollLeft||0,scrollY=scroller?.scrollTop||0;
  closeTypes();groups=[...new Set([...groups,...rows.map(r=>r.group)])];
  root.innerHTML=`<datalist id="tmKelList">${groups.map(g=>`<option value="${esc(g)}">`).join('')}</datalist><div class="v6kEditorHead tm-kpi-head"><h4 class="v6kTitle">KPI ${esc(p.nama)} · ${esc(bulan(period))}</h4><span class="v6kTag">${rows.length} indikator</span><p class="hint">Setiap indikator satu baris seperti KPI Sales. Geser tabel ↔ di HP; TYPE mengikuti brand yang dipilih.</p></div><div class="table-scroll v6kEditorScroll tm-kpi-grid"><table class="v6kTable tm-kpi-table"><thead><tr><th>Kelompok</th><th>Metrik</th><th>Brand</th><th>Filter TYPE</th><th>Min unit / DA</th><th>Bobot</th><th>Batas skor</th><th>Target</th><th>Aktual</th><th>Sumber aktual</th><th>Cakupan aktual</th><th>Label</th><th></th></tr></thead><tbody>${rows.map((r,n)=>`<tr class="tm-kpi-row"><td><input class="fi" list="tmKelList" ${field('group',n)} value="${esc(r.group)}" placeholder="Ketik kelompok KPI"></td><td><select class="fi" ${field('metric',n)}>${tmOptions(metrics,r.metric)}</select></td><td><select class="fi" ${field('brand',n)}>${tmOptions(allBrands,r.brand)}</select></td><td>${['QTY','DA'].includes(r.metric)||r.types.length?`<div class="v6kTp"><button class="v6kTpBtn" type="button" data-kpi-types="${n}" data-kind="filter">${typeName(r.types)} ▾</button></div>`:'<span class="hint">—</span>'}</td><td>${r.metric==='DA'?`<div class="tm-kpi-da">${input('minQty',n,r,'n')}<select class="fi" data-kpi-variant="${n}">${tmOptions([{value:'BASIC',label:'DA Biasa'},{value:'DAQ',label:'DAQ · Type Wajib'},{value:'IOT',label:'DA IoT · Per Promotor'},...(r.variant==='KEY'?[{value:'KEY',label:'DA KEY · Type Wajib'}]:[])],r.variant)}</select>${['DAQ','KEY'].includes(r.variant)?`<div class="v6kTp"><button class="v6kTpBtn" type="button" data-kpi-types="${n}" data-kind="required">${r.requirements[0]?.types?.length?typeName(r.requirements[0].types):'<span class="hint">pilih type wajib</span>'} ▾</button></div>`:''}${r.variant==='IOT'?input('perProm',n,r,'n'):''}</div>`:r.metric==='NOO'?input('minQty',n,r,'n'):r.metric==='IDDLE'?'<span class="v6kLocked">1 unit net</span>':'<span class="hint">—</span>'}</td><td>${input('weight',n,r,'n')}</td><td>${input('cap',n,r,'n')}</td><td>${input('target',n,r,'n')}${cfg.scope.mode==='ALL'&&r.source==='AUTO'?`<label class="tm-kpi-inline-check"><input type="checkbox" ${field('inherit',n)} ${r.inherit?'checked':''}> Ikut Sales jika cocok</label>`:''}</td><td>${r.source==='MANUAL'?input('actual',n,r,'n'):'<span class="tm-kpi-auto">Transaksi resmi Sales</span>'}</td><td><select class="fi" ${field('source',n)}>${tmOptions([{value:'AUTO',label:'Otomatis Sales'},{value:'MANUAL',label:'Manual Admin'}],r.source)}</select></td><td>${r.source==='MANUAL'?'<span class="hint">—</span>':`<select class="fi" ${field('scopeMode',n)}>${tmOptions([{value:'PAIR',label:'Dealer penugasan'},{value:'SALES',label:'Semua Sales cakupan'},{value:'DEALERS',label:'Dealer tertentu…'}],r.scopeMode)}</select>${r.scopeMode==='DEALERS'?`<input class="fi" ${field('scopeDealersText',n)} value="${esc(r.scopeDealersText||'')}" placeholder="Kode dealer, pisah koma" style="margin-top:4px">`:''}`}</td><td>${input('label',n,r)}</td><td class="tm-kpi-actions"><button class="chip" type="button" data-kpi-remove="${n}" aria-label="Hapus indikator ${n+1}">✕</button></td></tr>`).join('')}</tbody></table></div><div class="v6kSums" id="tmKpiSums"></div><div class="toolbar"><button class="chip" id="tmKpiAdd">+ Indikator</button><button class="chip" id="tmKpiCopy">Salin bulan sebelumnya</button><button class="chip" id="tmKpiCopyTo">Salin ke Telemarketing lain…</button></div><div class="toolbar tm-kpi-save"><label>Alasan perubahan<input class="fi" id="tmKpiReason" value="${esc(reason)}" minlength="5"></label><button class="chip primary" id="tmKpiSave">Simpan KPI / target / aktual</button><span id="tmKpiError" role="status"></span></div>`;
  root.querySelector('.tm-kpi-grid').scrollTo(scrollX,scrollY);
  const sums=()=>{const grouped={};rows.forEach(r=>grouped[r.group]=(grouped[r.group]||0)+(Number(r.weight)||0));$('tmKpiSums').innerHTML=Object.entries(grouped).map(([name,w])=>`<span class="${Math.abs(w-100)>.001?'bad':''}">${esc(name)}: ${num(w)}% ${Math.abs(w-100)>.001?'· harus 100%':'✓'}</span>`).join('');return Object.values(grouped).every(w=>Math.abs(w-100)<.001);};sums();
  root.querySelectorAll('[data-kpi-field]').forEach(el=>el.onchange=()=>{try{read();const r=rows[+el.dataset.row],key=el.dataset.kpiField;if(key==='metric'){r.types=[];r.requirements=[];r.minQty=r.metric==='DA'?2:1;r.variant='BASIC';if(r.metric==='MANUAL')r.source='MANUAL';}if(key==='brand'){r.types=[];r.requirements=[];if(r.variant==='IOT'&&r.brand==='ALL')r.variant='BASIC';}if(key==='source'&&r.source==='AUTO')r.actual=null;if(['metric','source','brand','scopeMode'].includes(key))draw();else sums();}catch(e){$('tmKpiError').textContent=e.message;}});
  root.querySelectorAll('[data-kpi-variant]').forEach(el=>el.onchange=()=>{try{read();const r=rows[+el.dataset.kpiVariant];r.variant=el.value;r.requirements=[];if(r.variant==='IOT'&&r.brand==='ALL')r.brand=a.brands.find(b=>/TECNO/i.test(b))||a.brands[0]||'ALL';if(r.variant==='DAQ'&&Number(r.minQty)<7)r.minQty=7;draw();}catch(e){$('tmKpiError').textContent=e.message;}});
  root.querySelectorAll('[data-kpi-types]').forEach(button=>button.onclick=event=>{event.stopPropagation();try{read();closeTypes();const r=rows[+button.dataset.kpiTypes],required=button.dataset.kind==='required',list=typeList(r.brand),selected=new Set(required?(r.requirements[0]?.types||[]):r.types);
   const pop=document.createElement('div');pop.className='v6kTpPop tm-kpi-type-pop';pop.innerHTML=`<b>${required?'TYPE wajib':'Filter TYPE'} · ${esc(r.brand)}</b><input class="fi" placeholder="Cari type…" data-q><div class="v6kTpList">${list.map(t=>`<label data-t="${esc(t.toUpperCase())}"><input type="checkbox" value="${esc(t)}" ${selected.has(t)?'checked':''}> ${esc(t)}</label>`).join('')||'<p class="hint">Belum ada TYPE untuk brand ini di Master Product.</p>'}</div><div class="toolbar"><button type="button" class="chip" data-clear>${required?'Kosongkan':'Semua type'}</button><button type="button" class="chip primary" data-apply>Pakai (${selected.size})</button></div>`;document.body.appendChild(pop);
   const rect=button.getBoundingClientRect();pop.style.top=Math.max(8,Math.min(rect.bottom+4,innerHeight-340))+'px';pop.style.left=Math.max(8,Math.min(rect.left,innerWidth-300))+'px';
   const apply=types=>{if(required)r.requirements=types.length?[{brand:r.brand,types,minQty:1}]:[];else r.types=types;closeTypes();draw();};
   pop.onclick=e=>e.stopPropagation();pop.querySelector('[data-q]').oninput=e=>{const query=e.target.value.toUpperCase();pop.querySelectorAll('label[data-t]').forEach(label=>label.style.display=label.dataset.t.includes(query)?'':'none');};pop.querySelectorAll('input[type=checkbox]').forEach(box=>box.onchange=()=>{pop.querySelector('[data-apply]').textContent='Pakai ('+pop.querySelectorAll('input:checked').length+')';});pop.querySelector('[data-clear]').onclick=()=>apply([]);pop.querySelector('[data-apply]').onclick=()=>apply([...pop.querySelectorAll('input:checked')].map(box=>box.value));pop.querySelector('[data-q]').focus();
  }catch(e){$('tmKpiError').textContent=e.message;}});
  root.querySelectorAll('[data-kpi-remove]').forEach(el=>el.onclick=()=>{read();rows.splice(+el.dataset.kpiRemove,1);draw();});
  $('tmKpiAdd').onclick=()=>{read();const r=normalize(tmDefaultIndicator());r.group=rows.at(-1)?.group||'KPI ALL BRAND';r.weight=0;rows.push(r);draw();};
  $('tmKpiCopyTo').onclick=()=>{try{read();const others=(a.people||[]).filter(x=>x.nik!==p.nik);if(!others.length)throw Error('Tidak ada Telemarketing lain.');
   modal('Salin KPI ke Telemarketing lain',`<p class="hint">Menyalin KPI yang tersimpan untuk <b>${esc(p.nama)}</b> · ${esc(bulan(period))}. Simpan dulu bila ada perubahan di layar.</p><div class="tm-copy-list">${others.map(x=>`<label><input type="checkbox" name="tmCopyTo" value="${esc(x.nik)}"> ${esc(x.nama)} <small>${esc(x.nik)}</small></label>`).join('')}</div><div class="toolbar"><label><input type="radio" name="tmCopyMode" value="SKIP" checked> Lewati yang sudah punya KPI</label><label><input type="radio" name="tmCopyMode" value="OVERWRITE"> Timpa KPI yang ada</label></div><div class="toolbar"><label><input type="checkbox" id="tmCopyTarget"> Salin target juga (aktual manual selalu dikosongkan)</label></div><label>Alasan<input class="fi" id="tmCopyWhy" placeholder="Minimal 5 karakter"></label><p id="tmCopyMsg" class="hint" role="alert"></p><button class="chip primary" id="tmCopyGo" type="button">Salin</button>`);
   $('tmCopyGo').onclick=async()=>{try{const t=[...document.querySelectorAll('[name=tmCopyTo]:checked')].map(x=>x.value);if(!t.length)throw Error('Pilih minimal satu Telemarketing.');$('tmCopyGo').disabled=true;const r=await rpc('apiTMKpiCopy',TOKEN,p.nik,period,t,document.querySelector('[name=tmCopyMode]:checked').value,$('tmCopyTarget').checked,$('tmCopyWhy').value);$('tmCopyMsg').innerHTML='Tersalin ke '+r.copied.length+' Telemarketing.'+(r.skipped.length?' Dilewati: '+r.skipped.map(x=>esc(x.nik+' ('+x.why+')')).join(', '):'');}catch(e){$('tmCopyMsg').textContent=e.message;}finally{if($('tmCopyGo'))$('tmCopyGo').disabled=false;}};}catch(e){$('tmKpiError').textContent=e.message;}};
  $('tmKpiCopy').onclick=async()=>{try{read();const d=new Date(period+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()-1);const prev=await rpc('apiTMKpiSettings',TOKEN,p.nik,d.toISOString().slice(0,7));if(!prev.indicators.length)throw Error('Kebijakan bulan lalu kosong.');rows=structuredClone(prev.indicators).map(r=>normalize({...r,target:null,actual:null}));draw();}catch(e){$('tmKpiError').textContent=e.message;}};
  $('tmKpiSave').onclick=async()=>{const btn=$('tmKpiSave');try{read();if(reason.trim().length<5)throw Error('Isi alasan minimal 5 karakter.');if(!rows.length||!sums())throw Error('Total bobot tiap kelompok harus 100%.');if(rows.some(r=>r.metric==='DA'&&['DAQ','KEY'].includes(r.variant)&&!r.requirements[0]?.types?.length))throw Error('Pilih TYPE wajib untuk DAQ / DA KEY.');btn.disabled=true;await rpc('apiTMKpiSave',TOKEN,p.nik,period,{revision:cfg.revision,indicators:rows,reason});cfg=await rpc('apiTMKpiSettings',TOKEN,p.nik,period);rows=structuredClone(cfg.indicators).map(normalize);draw();$('tmKpiError').textContent='Tersimpan.';}catch(e){$('tmKpiError').textContent=e.message;}finally{btn.disabled=false;}};
 };if(!window.TMKPITPDOC){window.TMKPITPDOC=true;document.addEventListener('click',closeTypes);}draw();
};

function tmValTypes(r,i){
 const g={};Object.entries(r.types||{}).forEach(([k,q])=>{const [b,...t]=k.split(' / ');(g[b]=g[b]||[]).push([t.join(' / ')||'—',q,(i&&(i.brand==='ALL'||i.brand===b)&&(!(i.types||[]).length||(i.types||[]).includes(t.join(' / '))))]);});
 const brands=Object.keys(g),n=Object.values(g).reduce((s,x)=>s+x.length,0);if(!brands.length)return '—';
 const head=brands.slice(0,2).map(esc).join(' · ')+(brands.length>2?' +'+(brands.length-2):'');
 const detail=brands.map(b=>`<div class="tmTyG"><b>${esc(b)}</b>${g[b].map(t=>`<span class="tmTyC ${t[2]?'k':''}">${esc(t[0])} <em>${num(t[1])}</em></span>`).join('')}</div>`).join('');
 return `<details class="tmTy"><summary>${head} <i>${n} type</i></summary><div class="tmTyD">${detail}</div></details>`;
}
function tmValidationTable(rows,kind,i,rule){
 i=i||{};rule=rule||{};const brand=(i.brand&&i.brand!=='ALL')?i.brand:'KPI',m=i.metric||'ST',failed=kind==='failed';
 const otherSum=r=>{let t=0;Object.entries(r.types||{}).forEach(([k,q])=>{if(i.brand&&i.brand!=='ALL'&&k.split(' / ')[0]!==i.brand)t+=q;});return t;};
 const other=r=>{const o={};Object.entries(r.types||{}).forEach(([k,q])=>{const b=k.split(' / ')[0];if(i.brand&&i.brand!=='ALL'&&b!==i.brand)o[b]=(o[b]||0)+q;});const t=Object.values(o).reduce((s,x)=>s+x,0);return t?num(t)+' · '+Object.keys(o).map(esc).join(', '):'—';};
 const dl=r=>'<b>'+esc(r.name)+'</b><small class="cellsub">'+esc(r.dealer)+'</small>'+(failed&&r.reason?`<small class="cellsub tmWhy">${esc(r.reason)}</small>`:'');
 const sum=f=>rows.reduce((t,r)=>t+(Number(f(r))||0),0),status=failed?'<b class="tmBad">✕ Belum</b>':'<b class="tmOk">✓ Terhitung</b>';
 let head,body,widths,total,numc=[];
 if(m==='DA'&&rule.perProm>0){
  head=['Dealer','Sales','Promotor '+brand,'ACC '+brand+' (unit)','Syarat','Status'];widths=[30,14,12,13,17,14];numc=[2,3];
  body=rows.map(r=>[dl(r),esc(r.sales||'—'),r.prom?num(r.prom)+' orang':'0 orang',num(r.acc||0),r.prom?num(r.prom)+' × '+num(rule.perProm)+' = '+num(r.need):'Tanpa promotor: min. '+num(r.need),status]);
  total=['Total · '+num(rows.length)+' dealer','',num(sum(r=>r.prom)),num(sum(r=>r.acc)),'',''];
 }else if(m==='DA'&&(rule.must||[]).length){
  head=['Dealer','Sales','ST '+brand+' (unit)','Type Wajib','Syarat','Status'];widths=[28,14,12,18,16,12];numc=[2];
  body=rows.map(r=>{const mt=r.mustTypes||{},ks=Object.keys(mt),ok=ks.filter(k=>mt[k]>0).length;return [dl(r),esc(r.sales||'—'),num(r.qty),`<details class="tmTy"><summary>${ok} dari ${ks.length} type ${ok===ks.length?'✓':''}</summary><div class="tmTyD">${ks.map(k=>`<span class="tmTyC ${mt[k]>0?'k':''}">${esc(k)} ${mt[k]>0?'✓':'✕'}</span>`).join('')}</div></details>`,'≥ '+num(r.min||rule.min||0)+' ST + semua Type Wajib',status];});
  total=['Total · '+num(rows.length)+' dealer','',num(sum(r=>r.qty)),'','',''];
 }else{
  const showOther=rows.some(r=>otherSum(r)>0),lab=brand==='KPI'?'Unit KPI':m+' '+brand+' (unit)';
  head=['Dealer','Sales',lab,'Nilai '+(brand==='KPI'?'KPI':brand)].concat(showOther?['Brand Lain (unit)']:[],['Type order']);
  widths=showOther?[28,13,10,16,14,19]:[32,15,11,19,23];numc=[2,3];
  body=rows.map(r=>[dl(r),esc(r.sales||'—'),num(r.qty),rupiah(r.value)].concat(showOther?[other(r)]:[],[tmValTypes(r,i)]));
  total=['Total · '+num(rows.length)+' dealer','',num(sum(r=>r.qty)),rupiah(sum(r=>r.value))].concat(showOther?[num(sum(otherSum))]:[],['']);
 }
 const th=['No'].concat(head),cols=[4].concat(widths.map(w=>Math.round(w*96/100)));
 const td=(c,k)=>`<td class="${numc.includes(k-1)?'n':''}">${c}</td>`;
 return `<div class="tm-vt-wrap"><table class="tm-vt"><colgroup><col style="width:27%"><col style="width:19%"><col style="width:12%"><col style="width:15%"><col style="width:14%"><col style="width:13%"></colgroup><thead><tr>${th.map((h,k)=>`<th class="${numc.includes(k-1)?'n':''}">${h}</th>`).join('')}</tr></thead><tbody>${body.map((r,n)=>`<tr><td class="tm-no">${n+1}</td>${r.map((c,k)=>td(c,k+1)).join('')}</tr>`).join('')||`<tr><td colspan="${th.length}" class="tm-empty">Tidak ada dealer.</td></tr>`}</tbody>${rows.length?`<tfoot><tr><td></td>${total.map((c,k)=>td(c,k+1)).join('')}</tr></tfoot>`:''}</table></div>`;
}
function tmValBar(){return `<button type="button" class="chip" onclick="const ds=[...(this.closest('#mbody,.modal')||document).querySelectorAll('details.tmTy')],o=ds.some(d=>d.open);ds.forEach(d=>d.open=!o);this.textContent=o?'Buka Semua':'Tutup Semua'">Buka Semua</button>`;}
function tmKpiValidationModal(i,k,back,who){const v=k.validation?.[i.id];if(!v){modal('Validasi · '+i.label,'<p>Rincian dealer tidak tersedia untuk akun ini.</p>');return;}let tab='counted',filter='';const draw=()=>{const rows=(v[tab]||[]).filter(r=>!filter||[r.name,r.dealer,r.sales].some(x=>String(x||'').toLowerCase().includes(filter.toLowerCase())));modal('Validasi KPI · '+i.label,`${back?'<div class="adm-back"><button class="chip" id="tmValBack">← Kembali ke KPI '+esc(who||'')+'</button></div>':''}<div class="tm-vbar"><button class="chip ${tab==='counted'?'primary':''}" id="tmValCounted">Terhitung · ${v.counted?.length||0}</button><button class="chip ${tab==='failed'?'primary':''}" id="tmValFailed">Belum memenuhi · ${v.failed?.length||0}</button><input class="fi" id="tmValSearch" placeholder="Cari dealer / Sales" value="${esc(filter)}"><span class="tm-vsp"></span>${tmValBar()}</div><p class="hint">${esc(v.note||'Belum memenuhi hanya menampilkan dealer yang sudah memiliki order resmi pada bulan ini.')}</p>${tmValidationTable(rows,tab,i,v.rule)}`);$('tmValBack')?.addEventListener('click',()=>back());$('tmValCounted').onclick=()=>{tab='counted';draw();};$('tmValFailed').onclick=()=>{tab='failed';draw();};$('tmValSearch').oninput=e=>{filter=e.target.value;const pos=e.target.selectionStart;draw();$('tmValSearch').focus();$('tmValSearch').setSelectionRange(pos,pos);};};draw();}
function tmMyKpiPanel(k){const val=n=>n==null?'—':num(n);return `<div class="scorehead"><b>${k.score==null?'—':pct(k.score)}</b><span>${esc(k.status)}</span></div>${k.groups.map(g=>`<details class="kgroup" open><summary>${esc(g.name)} <b>${g.score==null?'—':pct(g.score)}</b></summary><div class="table-scroll">${table(['Indikator','Bobot','Target','Aktual','Capaian','Skor','Status'],g.indicators.map(i=>[`<button class="textlink" data-tm-valid="${esc(i.id)}">${esc(i.label)} ↗</button><small class="cellsub">${esc(i.metric)} · ${esc(i.brand)}${i.types?.length?' · TYPE '+i.types.map(esc).join(', '):''}</small>`,pct(i.weight),val(i.target),val(i.actual),i.ach==null?'—':pct(i.ach),i.score==null?'—':pct(i.score),esc(i.state)]))}</div></details>`).join('')}`;}
tmKpiPage=async function(v,seq){v.innerHTML='<p class="v6load">Memuat KPI Telemarketing…</p>';if(tmIsMe()){
 const [own,ranking]=await Promise.all([rpc('apiTMKpi',TOKEN,REPORT.period),rpc('apiTMRank',TOKEN,REPORT.period)]);if(seq!==SEQUENCE)return;
 v.innerHTML=panel('Rincian KPI Telemarketing lain · satu atasan utama',`<div class="table-scroll">${table(['Nama','Indikator & target / aktual','Skor KPI','Rincian'],ranking.filter(x=>!x.mine).map(x=>[esc(x.nama),`<span id="tmPeerSummary${esc(x.nik)}">Klik rincian</span>`,x.score==null?'—':pct(x.score),`<button class="chip" data-tm-peer="${esc(x.nik)}">Lihat KPI</button>`]))}</div>`,'Nama lain dengan atasan utama yang sama')+panel('KPI saya · validasi pencapaian',tmMyKpiPanel(own.kpi),'Klik indikator untuk melihat dealer terhitung dan yang sudah order tetapi belum memenuhi syarat');
 v.querySelectorAll('[data-tm-valid]').forEach(el=>el.onclick=()=>{const i=own.kpi.groups.flatMap(g=>g.indicators).find(i=>i.id===el.dataset.tmValid);tmKpiValidationModal(i,own.kpi);});v.querySelectorAll('[data-tm-peer]').forEach(el=>el.onclick=()=>tmPersonKpi(el.dataset.tmPeer));
 }else{const rows=await rpc('apiTMRank',TOKEN,REPORT.period);if(seq!==SEQUENCE)return;v.innerHTML=panel('KPI Telemarketing · Peringkat',tmRankBoard(rows),'Diurutkan dari skor tertinggi · klik nama untuk rincian per indikator');v.querySelectorAll('[data-tm-kpi]').forEach(el=>el.onclick=()=>tmPersonKpi(el.dataset.tmKpi));}v.querySelectorAll('section.panel').forEach(el=>el.dataset.v2SkipFold='1');};
tmPersonKpi=async function(nik){try{const r=await rpc('apiTMKpi',TOKEN,REPORT.period,nik,$('tmRankBrand')?.value||'ALL');modal('KPI · '+r.person.nama,tmMyKpiPanel(r.kpi));$('mbody').querySelectorAll('[data-tm-valid]').forEach(el=>el.onclick=()=>{const i=r.kpi.groups.flatMap(g=>g.indicators).find(i=>i.id===el.dataset.tmValid);tmKpiValidationModal(i,r.kpi,()=>tmPersonKpi(nik),r.person.nama);});}catch(e){fail(e);}};

function kpiOwnValidationPanel(v){const role=BOOT?.user?.role;if(!['SALES','ASM','RGM'].includes(role))return;const target=document.createElement('details');target.className='panel foldPanel';target.id='ownKpiValidation';target.innerHTML=`<summary>Validasi KPI Saya · ${esc(role)}<small>Klik indikator untuk melihat dealer yang terhitung dan belum memenuhi</small></summary><div class="pb" id="ownKpiValidationBody"><p class="hint">Buka panel untuk memuat target dan aktual.</p></div>`;const before=v.querySelector('#teamKpiPanel');if(before)before.before(target);else v.append(target);
 let ready=false;target.ontoggle=async()=>{if(!target.open||ready)return;const body=$('ownKpiValidationBody');body.innerHTML='<p class="hint">Memuat rincian KPI…</p>';try{const k=await rpc('apiPersonKpi',TOKEN,REPORT.period,BOOT.user.nik);if(!body.isConnected)return;body.innerHTML=`<p class="hint">Skor KPI saya: <b>${k.score==null?'—':pct(k.score)}</b>. Angka aktual keseluruhan tetap utuh saat dealer difilter.</p>${k.groups.map((g,gi)=>`<h4>${esc(g.name)}</h4><div class="table-scroll">${table(['Indikator','Bobot','Target','Aktual','Capaian','Rincian dealer'],g.indicators.map((i,ii)=>[esc(i.label||i.metric+' '+i.brand),pct(i.weight),num(i.target),num(i.actual),i.ach==null?'—':pct(i.ach),`<button class="chip" data-own-valid="${gi}:${ii}">Lihat terhitung / belum memenuhi</button>`]))}</div>`).join('')}`;body.querySelectorAll('[data-own-valid]').forEach(el=>el.onclick=()=>{const [gi,ii]=el.dataset.ownValid.split(':').map(Number);kpiOwnValidationModal(gi,ii).catch(fail);});ready=true;}catch(e){body.textContent=e.message;}};
}
async function kpiOwnValidationModal(gi,ii,asNik,asRole,asName,back){let asm='',sales='',tab='counted';const subjRole=asNik?asRole:BOOT.user.role;const fetchRows=()=>rpc('apiKpiValidation',TOKEN,REPORT.period,gi,ii,asm,sales,asNik||null);let data=await fetchRows();const draw=()=>{const i=data.indicator,rows=data[tab]||[];modal('Validasi · '+(i.label||i.metric+' '+i.brand),`${back?'<div class="adm-back"><button class="chip" id="valBack">← Kembali ke KPI '+esc(asName||'')+'</button></div>':''}${asNik?`<div class="adm-as">Dilihat sebagai: <b>${esc(asName||asNik)}</b> <span>${esc(asRole||'')} · ${esc(REPORT.period)} · mode kroscek, hanya baca</span></div>`:''}<p class="hint">Target ${num(i.target)} · aktual ${num(i.actual)} · capaian ${i.ach==null?'—':pct(i.ach)}. Filter hanya mengubah daftar dan subtotal di bawah.</p><div class="tm-vbar">${subjRole==='RGM'?`<select class="fi" id="ownValAsm" aria-label="ASM">${tmOptions(data.filters.asms.map(x=>({value:x.nik,label:x.nama})),asm,'Semua ASM')}</select>`:''}${subjRole!=='SALES'?`<select class="fi" id="ownValSales" aria-label="Sales">${tmOptions(data.filters.sales.filter(x=>!asm||data.counted.concat(data.failed).some(r=>r.asmNik===asm&&r.salesNik===x.nik)).map(x=>({value:x.nik,label:x.nama})),sales,'Semua Sales')}</select>`:''}<button class="chip ${tab==='counted'?'primary':''}" id="ownValCounted">Terhitung · ${data.counted.length}</button><button class="chip ${tab==='failed'?'primary':''}" id="ownValFailed">Sudah order, belum memenuhi · ${data.failed.length}</button><span class="tm-vsp"></span><span class="hint tm-vsub">${num(data.filtered.dealers)} dealer · ${num(data.filtered.qty)} unit · ${rupiah(data.filtered.value)}</span>${tmValBar()}${asNik?'<button class="chip adm-x" id="admValExport">Export dealer indikator ini</button>':''}</div>${tmValidationTable(rows,tab,data.indicator,data.rule)}`);$('admValExport')?.addEventListener('click',()=>admValExport(data,asName||asNik,asRole));$('valBack')?.addEventListener('click',()=>back());$('ownValCounted').onclick=()=>{tab='counted';draw();};$('ownValFailed').onclick=()=>{tab='failed';draw();};$('ownValAsm')?.addEventListener('change',async e=>{asm=e.target.value==='ALL'?'':e.target.value;sales='';data=await fetchRows();draw();});$('ownValSales')?.addEventListener('change',async e=>{sales=e.target.value==='ALL'?'':e.target.value;data=await fetchRows();draw();});};draw();}

tmRankPage=async function(v,seq){const boot=tmIsMe()?await tmEnsureBoot():null,brands=boot?sortedUnique(boot.pairs.map(x=>x.brand)):REPORT.brands.map(b=>b.brand);v.innerHTML=`<div class="toolbar"><label>Cakupan<select class="fi" id="tmRankScope"><option value="PEER">Satu atasan utama</option><option value="NATIONAL">Nasional</option></select></label><label>Brand KPI<select class="fi" id="tmRankBrand">${tmOptions(brands,'ALL','Seluruh KPI')}</select></label></div><div id="tmRankRows"></div>`;const draw=async()=>{const scope=$('tmRankScope').value,rows=await rpc('apiTMRank',TOKEN,REPORT.period,$('tmRankBrand').value,scope);if(seq!==SEQUENCE)return;const mine=rows.find(x=>x.mine);$('tmRankRows').innerHTML=panel('Peringkat Telemarketing · '+(scope==='NATIONAL'?'Nasional':'Satu atasan utama'),`<div class="tm-rank-position">Posisi saya: <b>${mine?.rank?'#'+num(mine.rank):'—'}</b> dari ${num(rows.length)} Telemarketing</div>`+table(['Peringkat','Telemarketing','KPI','Status'],rows.map(x=>[x.rank||'—',x.canOpen?`<button class="textlink ${x.mine?'tm-me':''}" data-tm-kpi="${esc(x.nik)}">${esc(x.nama)} ↗</button>`:esc(x.nama),x.score==null?'—':pct(x.score),esc(x.status)])),'Rincian target/aktual rekan hanya bisa dibuka jika atasan utama sama.');$('tmRankRows').querySelectorAll('[data-tm-kpi]').forEach(el=>el.onclick=()=>tmPersonKpi(el.dataset.tmKpi));};$('tmRankScope').onchange=()=>draw().catch(fail);$('tmRankBrand').onchange=()=>draw().catch(fail);await draw();};

function tmRankBoard(rows){
 const keys=[],seen={};rows.forEach(r=>(r.ind||[]).forEach(i=>{if(!seen[i.key]){seen[i.key]=1;keys.push({key:i.key,label:i.label,weight:i.weight});}}));
 const tone=v=>v==null?'':v>=100?'tm-g':v>=80?'tm-y':'tm-r',chip=v=>v==null?'—':`<span class="tm-pill ${tone(v)}">${pct(v)}</span>`;
 const head1=`<tr><th rowspan="2">#</th><th rowspan="2">Telemarketing</th>${keys.map(k=>`<th colspan="3" class="tm-ind">${esc(k.label)} <span>bobot ${num(k.weight)}%</span></th>`).join('')}<th rowspan="2" class="n">Skor KPI</th></tr>`;
 const head2=`<tr>${keys.map(()=>'<th class="n">Target / Aktual</th><th class="n">% Achv</th><th class="n">Poin</th>').join('')}</tr>`;
 const body=rows.map((r,n)=>{const by={};(r.ind||[]).forEach(i=>by[i.key]=i);return `<tr><td><b>${r.rank||'—'}</b></td><td>${r.canOpen?`<button class="textlink ${r.mine?'tm-me':''}" data-tm-kpi="${esc(r.nik)}">${esc(r.nama)} ↗</button>`:esc(r.nama)}<small class="cellsub">${esc(r.status)}</small></td>${keys.map(k=>{const i=by[k.key];return i?`<td class="n">${i.target==null?'—':num(i.target)} / <b>${i.actual==null?'—':num(i.actual)}</b></td><td class="n">${chip(i.ach)}</td><td class="n">${i.score==null?'—':num(Math.round(i.score*i.weight)/100)}</td>`:'<td class="n">—</td><td class="n">—</td><td class="n">—</td>';}).join('')}<td class="n">${chip(r.score)}</td></tr>`;}).join('');
 return `<div class="table-scroll"><table class="tm-board"><thead>${head1}${head2}</thead><tbody>${body||'<tr><td colspan="9">Belum ada Telemarketing dalam cakupan.</td></tr>'}</tbody></table></div>`;
}

/* ===== KPI grid berwarna (dipakai Sales/ASM popup, Telemarketing, Validasi KPI Saya) ===== */
function kpiGridHtml(k,o){
 o=o||{};const limited=!!o.limited;const skorOf=o.scoreFn||(i=>typeof weightedKpiIndicatorScore==='function'?weightedKpiIndicatorScore(i):(i.score==null?null:i.score*i.weight));
 if(!k||!k.groups||!k.groups.length)return '<div class="empty">Kebijakan KPI belum diisi untuk bulan dan wilayah ini.</div>';
 const pal=['b','g','p','o'],val=n=>n==null?'—':num(n),sc=n=>n==null?'—':pct(n);
 const mc=m=>{m=String(m||'').toUpperCase();return /^(DA|DAQ)/.test(m)?'g':m==='SO'?'o':m==='NOO'?'p':m==='IDDLE'||m==='IDLE'?'a':m==='OMZET'?'br':'b';};
 const tone=v=>v==null?'':v>=100?'g':v>=80?'y':'r';
 const head=`<div class="kg-top"><div class="kg-score"><small>${esc(o.title||'SKOR KPI')}</small><b>${sc(k.score)}</b></div><div class="kg-meta">${esc(k.status||'')}${k.count?'<br>Rata-rata '+k.count+' kelompok yang berlaku':''}</div></div>`;
 const groups=k.groups.map((g,gi)=>{
  const rows=g.indicators.map((i,ii)=>{
   const nm=esc(i.label||(i.metric+' '+(i.brand||'')));
   const attr=o.attr?o.attr(g,i,gi,ii):'';
   const name=attr?`<button class="textlink kg-name" ${attr}>${nm} ↗</button>`:`<span class="kg-name">${nm}</span>`;
   const sub=(i.types&&i.types.length?'TYPE '+i.types.map(esc).join(', '):'')+(!limited&&i.metric==='DA'&&(i.minDA||i.minQty)?(i.types&&i.types.length?' · ':'')+'Min '+num(i.minDA||i.minQty)+' unit':'');
   const a=i.ach==null?null:i.ach,w=Math.max(0,Math.min(100,a||0));
   const pill=a==null?'—':`<span class="kg-pill ${tone(a)}">${pct(a)}</span>`;
   const capaian=pill;
   return `<tr class="kg-r kr-${mc(i.metric)}"><td class="kg-i"><span class="kg-tag">${esc(i.metric||'')}</span>${name}${sub?'<small>'+sub+'</small>':''}</td><td>${pct(i.weight)}</td>${limited?'':`<td>${val(i.target)}</td><td>${val(i.actual)}</td>`}<td class="kg-c">${capaian}</td><td class="kg-s">${sc(skorOf(i,g))}</td></tr>`;
  }).join('');
  return `<section class="kg-g kp-${pal[gi%4]}"><header><span>${esc(g.name)}</span><b>${sc(g.score)}</b></header><div class="table-scroll"><table class="kg-t"><thead><tr><th>Indikator</th><th>Bobot</th>${limited?'':'<th>Target</th><th>Aktual</th>'}<th>Capaian</th><th>Skor</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
 }).join('');
 return head+`<div class="kg-grid">${groups}</div>`+(o.note===false?'':'<div class="info">Target 0 tidak diwajibkan. Skor kelompok memakai bobot indikator yang berlaku; KPI akhir = rata-rata skor kelompok.</div>');
}
function tmSkorFn_(i,g){const w=g.indicators.filter(x=>x.state==='BERLAKU').reduce((n,x)=>n+x.weight,0);return i.score==null||i.state!=='BERLAKU'||!w?null:i.score*i.weight/w;}
if(typeof tmKpiHtml!=='undefined')tmKpiHtml=function(k,limited){return kpiGridHtml(k,{limited:limited,title:'KPI TELEMARKETING',scoreFn:tmSkorFn_});};
tmMyKpiPanel=function(k){return kpiGridHtml(k,{title:'SKOR KPI SAYA',scoreFn:tmSkorFn_,attr:(g,i)=>'data-tm-valid="'+esc(i.id)+'"'});};
kpiOwnValidationPanel=function(v){const role=BOOT?.user?.role;if(!['SALES','ASM','RGM'].includes(role))return;const target=document.createElement('details');target.className='panel foldPanel';target.id='ownKpiValidation';target.innerHTML=`<summary>Validasi KPI Saya · ${esc(role)}<small>Klik indikator untuk melihat dealer yang terhitung dan belum memenuhi</small></summary><div class="pb" id="ownKpiValidationBody"><p class="hint">Buka panel untuk memuat target dan aktual.</p></div>`;const before=v.querySelector('#teamKpiPanel');if(before)before.before(target);else v.append(target);
 let ready=false;target.ontoggle=async()=>{if(!target.open||ready)return;const body=$('ownKpiValidationBody');body.innerHTML='<p class="hint">Memuat rincian KPI…</p>';try{const k=await rpc('apiPersonKpi',TOKEN,REPORT.period,BOOT.user.nik);if(!body.isConnected)return;body.innerHTML=kpiGridHtml(k,{title:'SKOR KPI SAYA',note:false,attr:(g,i,gi,ii)=>'data-own-valid="'+gi+':'+ii+'"'});body.querySelectorAll('[data-own-valid]').forEach(el=>el.onclick=()=>{const [gi,ii]=el.dataset.ownValid.split(':').map(Number);kpiOwnValidationModal(gi,ii).catch(fail);});ready=true;}catch(e){body.textContent=e.message;}};
};

/* ===== Kroscek KPI Admin: pencarian nama/NIK, popup KPI, export dealer indikator ===== */
function admValExport(data,name,role){const i=data.indicator,rows=[['KROSCEK VALIDASI KPI',name,role,REPORT.period],['Indikator',i.label||i.metric+' '+i.brand,'Target',i.target,'Aktual',i.actual],[],['STATUS','NO','KODE DEALER','DEALER','SALES','ASM','QTY','NILAI','KETERANGAN']];[['TERHITUNG',data.counted],['BELUM MEMENUHI',data.failed]].forEach(([st,list])=>list.forEach((r,n)=>rows.push([st,n+1,r.dealer,r.name,r.sales,r.asm,r.qty,r.value,st==='TERHITUNG'?'':r.reason])));downloadContactXlsx(rows);}
function admKpiOpen(p){if(p.role==='TELEMARKETING'){tmPersonKpi(p.nik);return;}admRankPerson(p.nik);}
async function admRankPerson(nik){modal('Rincian KPI','<p role="status">Memuat rincian KPI…</p>');const token=TOKEN;try{const r=await rpc('apiRankDetail',token,REPORT.period,nik);if(token!==TOKEN||!$('mask').classList.contains('on'))return;$('mtitle').textContent=r.nama+' · '+r.role;$('mbody').innerHTML=`<div class="adm-as">Dilihat sebagai: <b>${esc(r.nama)}</b> <span>${esc(r.role)} · ${esc(r.region||'')} · ${esc(REPORT.period)} · mode kroscek, hanya baca</span></div>`+kpiGridHtml(r.kpi,{title:'SKOR KPI',attr:(g,i,gi,ii)=>'data-adm-valid="'+gi+':'+ii+'"'});$('mbody').querySelectorAll('[data-adm-valid]').forEach(el=>el.onclick=()=>{const [gi,ii]=el.dataset.admValid.split(':').map(Number);kpiOwnValidationModal(gi,ii,nik,r.role,r.nama,()=>admRankPerson(nik)).catch(fail);});}catch(e){$('mbody').innerHTML='<p>'+esc(e.message)+'</p>';}}
function admKpiSearchInit(host){if(!host||!['ADMIN','SUPER ADMIN'].includes(BOOT?.user?.role))return;host.innerHTML=`<div class="panel adm-search"><div class="ph"><h3>Cari &amp; Kroscek KPI</h3></div><div class="pb"><div class="adm-bar"><input class="fi" id="admQ" placeholder="Cari nama atau NIK, mis. fendi / 2024.12" aria-label="Cari nama atau NIK" autocomplete="off"><select class="fi" id="admRole" aria-label="Jabatan"><option value="ALL">Semua jabatan</option><option value="SALES">Sales</option><option value="ASM">ASM</option><option value="RGM">RGM</option><option value="TELEMARKETING">Telemarketing</option></select></div><div id="admRes"><p class="hint">Ketik minimal 2 huruf. Klik nama untuk membuka KPI, lalu klik nama indikator untuk validasi dealer (hanya baca, tercatat di audit log).</p></div></div></div>`;let timer=null,seq=0;const run=async()=>{const q=$('admQ').value.trim();if(q.length<2){$('admRes').innerHTML='<p class="hint">Ketik minimal 2 huruf.</p>';return;}const my=++seq;$('admRes').innerHTML='<p class="hint">Mencari…</p>';try{const rows=await rpc('apiKpiSearch',TOKEN,REPORT.period,q,$('admRole').value);if(my!==seq)return;const hi=s=>esc(s).replace(new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig'),'<mark>$1</mark>');$('admRes').innerHTML=rows.length?`<div class="table-scroll"><table><thead><tr><th>Nama</th><th>NIK</th><th>Jabatan</th><th>Wilayah</th><th>KPI</th><th>Status</th></tr></thead><tbody>${rows.map((r,n)=>`<tr><td><button class="textlink" data-adm-open="${n}">${hi(r.nama)} ↗</button></td><td>${hi(String(r.nik))}</td><td>${esc(r.role)}</td><td>${esc(r.wilayah||'')}</td><td>${r.score==null?'—':pct(r.score)}</td><td>${esc(r.status||'')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Tidak ada nama atau NIK yang cocok.</p>';$('admRes').querySelectorAll('[data-adm-open]').forEach(b=>b.onclick=()=>admKpiOpen(rows[Number(b.dataset.admOpen)]));}catch(e){$('admRes').innerHTML='<p class="hint">'+esc(e.message)+'</p>';}};$('admQ').oninput=()=>{clearTimeout(timer);timer=setTimeout(run,300);};$('admRole').onchange=run;}

/* ===== Aktivitas Telemarketing · tampilan Semua Telemarketing + Daily Report ===== */
(function(){
 const baseAct=tmActivityPage;
 const teamOn=()=>tmState.team===undefined?true:!!tmState.team;
 const scoreCls=s=>s==null?'':s>=100?'g':s>=80?'y':'r';
 const desk=()=>window.matchMedia('(min-width:761px)').matches;
 const reset=()=>{tmState.filters={q:'',brand:'ALL',big:'ALL',region:'ALL',state:'ALL'};};
 const select=(people,cur)=>`<label>Telemarketing<select class="fi" id="tmPerson2"><option value="__TEAM__"${cur==='__TEAM__'?' selected':''}>★ SEMUA TELEMARKETING</option>${people.map(p=>`<option value="${esc(p.nik)}"${cur===p.nik?' selected':''}>${esc(p.nama)}</option>`).join('')}</select></label>`;
 function bindSelect(){const s=$('tmPerson2');if(s)s.onchange=()=>{if(s.value==='__TEAM__'){tmState.team=true;}else{tmState.team=false;tmState.person=s.value;reset();}render();};}
 tmActivityPage=async function(v,seq,home){
  if(home||!teamOn()){
   await baseAct(v,seq,home);if(seq!==SEQUENCE||home)return;
   const old=$('tmPerson');
   if(old){old.closest('label').outerHTML=select(tmState.activity.people,tmState.person);}
   else if(tmIsMe()&&v.firstElementChild){v.insertAdjacentHTML('afterbegin',`<div class="toolbar">${select([{nik:BOOT.user.nik,nama:'AKTIVITAS SAYA'}],BOOT.user.nik)}</div>`);}
   bindSelect();return;
  }
  v.innerHTML='<p class="v6load">Memuat rincian semua Telemarketing…</p>';
  const t=await rpc('apiTMTeam',TOKEN,REPORT.period);if(seq!==SEQUENCE)return;tmState.teamData=t;
  const people=tmIsMe()?[{nik:BOOT.user.nik,nama:'AKTIVITAS SAYA'}]:t.rows.map(r=>({nik:r.nik,nama:r.nama}));
  const q=(tmState.teamQ||'').toLowerCase(),sort=tmState.teamSort||'fuScheduled',dir=tmState.teamDir||(sort==='nama'||sort==='sub'?1:-1);
  let rows=t.rows.filter(r=>!q||(r.nama+' '+r.atasan+' '+r.subs.join(' ')).toLowerCase().includes(q));
  const val=r=>sort==='nama'?r.nama:sort==='sub'?(r.subs[0]||''):sort==='score'?(r.score==null?-1:r.score):(r[sort]||0);
  rows=rows.slice().sort((a,b)=>{const x=val(a),y=val(b);const c=typeof x==='string'?x.localeCompare(y):x-y;return (c*dir)||a.nama.localeCompare(b.nama)});
  const sum=k=>rows.reduce((n,r)=>n+(r[k]||0),0),sc=rows.filter(r=>r.score!=null),avg=sc.length?sc.reduce((n,r)=>n+r.score,0)/sc.length:null;
  const regCell=r=>r.subs.length?`<span class="tt-sub">${esc(r.subs[0])}</span>${r.subs.length>1?` <span class="tt-more" title="${esc(r.subs.join(', '))}" tabindex="0">+${r.subs.length-1}</span>`:''}`:'<span class="hint">—</span>';
  const sel=tmState.sel&&rows.some(r=>r.nik===tmState.sel)?tmState.sel:null;tmState.sel=sel;
  const body=rows.map(r=>`<tr class="${scoreCls(r.score)}${r.nik===sel?' on':''}" data-tt-open="${esc(r.nik)}"><td><span class="tt-tag">TM</span><button class="textlink tt-nm" data-tt-open="${esc(r.nik)}">${esc(r.nama)}</button></td><td class="tt-regc">${regCell(r)}</td><td class="n">${num(r.dealers)}</td><td class="n"><span class="tt-b ${r.fuScheduled?(r.fuDone>=r.fuScheduled?'g':'b'):'z'}">${num(r.fuDone)} / ${num(r.fuScheduled)}</span></td><td class="n"><span class="tt-b ${r.orderToday?'g':'z'}">${num(r.orderToday)}</span></td><td class="n">${r.score==null?'—':`<span class="tt-b ${scoreCls(r.score)}">${pct(r.score)}</span>`}</td></tr>`).join('');
  const mob=rows.map(r=>`<button type="button" class="tt-mc ${scoreCls(r.score)}" data-tt-open="${esc(r.nik)}"><div class="tt-mt"><b>${esc(r.nama)}</b><i>Rincian ›</i></div><small>${esc(r.atasan||'—')} RGM · ${esc(r.subs[0]||'—')}${r.subs.length>1?' +'+(r.subs.length-1):''}</small><div class="tt-mg"><span class="c1"><b>${num(r.dealers)}</b>Dealer dihandle</span><span class="c1"><b>${num(r.fuDone)} <u>/ ${num(r.fuScheduled)}</u></b>FU hari ini</span><span class="c2"><b>${num(r.orderToday)}</b>Order hari ini</span><span class="c3"><b>${r.score==null?'—':pct(r.score)}</b>Skor KPI</span></div></button>`).join('');
  const canX=t.canExport,fuAll=sum('dealersFU'),dAll=sum('dealers');
  v.innerHTML=cards([['Perlu FU hari ini',num(sum('fuScheduled')),'Jadwal FU jatuh hari ini · seluruh tim'],['Dealer ditugaskan',num(dAll),'Total seluruh tim'],['Rata-rata skor KPI',avg==null?'—':pct(avg),'Rata-rata Telemarketing terlihat'],['Dealer sudah di-FU',num(fuAll)+' / '+num(dAll),'Bulan ini · '+(dAll?Math.round(fuAll/dAll*100):0)+'%']])
   +`<div class="tt-split"><section class="tt-kt"><header>Rincian per Telemarketing <span>${rows.length} orang</span></header><div class="toolbar tt-tools"><label>Cari<input class="fi" id="ttQ" value="${esc(tmState.teamQ||'')}" placeholder="Nama / RGM / sub region"></label><button class="chip primary" id="ttReport">📋 Salin Report Harian</button>${canX?'<button class="chip" id="ttXlsx">⬇ Export Excel</button>':''}</div>`
   +(rows.length?`<div class="table-scroll tt-wrap"><table class="tt-t" data-tp="1" data-sort-ready="1"><colgroup><col style="width:27%"><col style="width:19%"><col style="width:12%"><col style="width:16%"><col style="width:14%"><col style="width:12%"></colgroup><thead><tr><th data-sk="nama">Telemarketing${sort==='nama'?(dir>0?' ▲':' ▼'):''}</th><th data-sk="sub">Region${sort==='sub'?(dir>0?' ▲':' ▼'):''}</th><th class="n" data-sk="dealers">Dealer${sort==='dealers'?(dir>0?' ▲':' ▼'):''}</th><th class="n" data-sk="fuScheduled">FU hari ini${sort==='fuScheduled'?(dir>0?' ▲':' ▼'):''}<small>selesai / jadwal</small></th><th class="n" data-sk="orderToday">Order hari ini${sort==='orderToday'?(dir>0?' ▲':' ▼'):''}</th><th class="n" data-sk="score">Skor KPI${sort==='score'?(dir>0?' ▲':' ▼'):''}</th></tr></thead><tbody>${body}</tbody><tfoot><tr><td>TOTAL TIM</td><td></td><td class="n">${num(dAll)}</td><td class="n">${num(sum('fuDone'))} / ${num(sum('fuScheduled'))}</td><td class="n">${num(sum('orderToday'))}</td><td class="n">${avg==null?'—':pct(avg)}</td></tr></tfoot></table></div><div class="tt-mob">${mob}</div>`:'<div class="tm-empty"><b>Tidak ada Telemarketing yang terlihat.</b></div>')
   +`<p class="hint tt-note">Klik nama untuk rincian. Skor KPI hijau ≥ 100%, kuning 80–99%, merah &lt; 80%. Rincian indikator KPI hanya dapat dibuka RGM ke atas dan Admin.</p></section><aside class="tt-side" id="ttSide"></aside></div><div id="ttActWrap"></div>`;
  bindSelect();
  $('ttQ').onchange=e=>{tmState.teamQ=e.target.value;render();};
  $('ttQ').onkeydown=e=>{if(e.key==='Enter'){tmState.teamQ=e.target.value;render();}};
  document.querySelectorAll('.tt-t th[data-sk]').forEach(h=>h.onclick=()=>{const k=h.dataset.sk;if((tmState.teamSort||'fuScheduled')===k)tmState.teamDir=-(tmState.teamDir||(k==='nama'||k==='sub'?1:-1));else{tmState.teamSort=k;tmState.teamDir=(k==='nama'||k==='sub')?1:-1}render();});
  v.querySelectorAll('[data-tt-open]').forEach(b=>b.onclick=ev=>{ev.stopPropagation();tmTeamPick(b.dataset.ttOpen);});
  $('ttReport').onclick=tmDailyReport;
  if(canX)$('ttXlsx').onclick=()=>{const h=['TELEMARKETING','RGM','SUB REGION','DEALER DIHANDLE','DEALER SUDAH FU BULAN INI','FU HARI INI (SELESAI)','FU HARI INI (JADWAL)','ORDER HARI INI','ST RESMI MTD','SKOR KPI'];downloadContactXlsx([['AKTIVITAS TELEMARKETING',REPORT.period,t.today],[],h].concat(rows.map(r=>[r.nama,r.atasan,r.subs.join(', '),r.dealers,r.dealersFU,r.fuDone,r.fuScheduled,r.orderToday,r.stMtd,r.score==null?'':Math.round(r.score*10)/10])));};
  bind();
  if(desk()){ttSide(sel);if(sel)ttLoadAct(sel,seq);}
 };
 function detailHtml(r,modalMode){
  const pctFU=r.dealers?Math.round(r.dealersFU/r.dealers*100):0;
  const places=r.places.length?r.places.map(p=>`<div class="tt-reg"><span>${esc(p.sub)}</span><span><b>${num(p.st)}</b><em>ST</em> &nbsp;<b>${num(p.fu)}</b><em>FU</em></span></div>`).join('')+(r.places.length>1?`<div class="tt-reg tt-tot"><span>Total</span><span>${num(r.stToday)} ST · ${num(r.fuTotal)} FU</span></div>`:''):'<div class="tt-reg"><span class="hint">Belum ada aktivitas hari ini</span><b>0 · 0</b></div>';
  const box=(c,v,l)=>`<span class="${c}"><b>${v}</b>${l}</span>`;
  const canKpi=!tmIsMe();
  return `<div class="tt-sh"><div><b>${esc(r.nama)}</b><small>${esc(r.atasan||'—')}${r.atasan?' (RGM)':''} · ${esc(r.subs.slice(0,3).join(', '))}${r.subs.length>3?' +'+(r.subs.length-3):''}</small></div>${r.score==null?'':`<span class="tt-b ${scoreCls(r.score)} tt-big">${pct(r.score)}</span>`}</div>
   <div class="tt-sum">${box('c1',num(r.dealers),'Dealer dihandle')}${box('c1',num(r.dealersFU)+' <u>('+pctFU+'%)</u>','Sudah FU bln ini')}${box('c1',num(r.fuDone)+' / '+num(r.fuScheduled),'FU hari ini (selesai / jadwal)')}${box('c2',num(r.orderToday),'Order hari ini')}${box('c2',num(r.stMtd),'ST resmi MTD')}${box('c3',r.score==null?'—':pct(r.score),'Skor KPI')}</div>
   <div class="tt-lbl">AKTIVITAS HARI INI PER SUB REGION</div>${places}
   <p class="hint">Order hari ini = form order tersimpan hari ini (real-time). ST resmi MTD = unit transaksi resmi dealer yang dihandle, sesuai data resmi terakhir yang masuk.</p>
   <div class="tt-act">${modalMode&&(!tmIsMe()||r.nik===BOOT.user.nik)?'<button class="chip primary" id="ttFull">Buka aktivitas lengkap</button>':''}${canKpi?'<button class="chip" id="ttKpi">Lihat KPI</button>':'<button class="chip" disabled title="Rincian indikator KPI hanya untuk RGM ke atas">🔒 Rincian KPI terkunci</button>'}</div>`;
 }
 function ttSide(nik){
  const side=$('ttSide');if(!side)return;const r=(tmState.teamData?.rows||[]).find(x=>x.nik===nik);
  side.innerHTML=r?detailHtml(r,false):'<div class="tt-empty"><b>Rincian Telemarketing</b><br>Klik nama Telemarketing di tabel untuk melihat rincian di sini.</div>';
  if(r&&$('ttKpi'))$('ttKpi').onclick=()=>tmPersonKpi(nik);
 }
 async function ttLoadAct(nik,seq){
  const wrap=$('ttActWrap');if(!wrap)return;const r=tmState.teamData.rows.find(x=>x.nik===nik);
  if(tmIsMe()&&nik!==BOOT.user.nik){wrap.innerHTML='';return;}
  wrap.innerHTML=`<h3 class="tt-acth">Aktivitas · ${esc(r?.nama||'')}</h3><div id="ttActBody"><p class="v6load">Memuat aktivitas…</p></div>`;
  const keep={person:tmState.person,team:tmState.team};tmState.person=nik;tmState.team=false;
  try{const body=$('ttActBody');await baseAct(body,SEQUENCE,false);body.querySelector('#tmPerson')?.closest('.toolbar')?.remove();}
  catch(e){wrap.innerHTML='';}
  finally{tmState.team=true;if(keep.person)tmState.person=nik;}
 }
 window.tmTeamPick=function(nik){
  if(desk()){tmState.sel=nik;document.querySelectorAll('.tt-t tbody tr').forEach(tr=>tr.classList.toggle('on',tr.dataset.ttOpen===nik));ttSide(nik);ttLoadAct(nik,SEQUENCE);return;}
  tmTeamDetail(nik);
 };
 window.tmTeamDetail=function(nik){
  const r=(tmState.teamData?.rows||[]).find(x=>x.nik===nik);if(!r)return;
  modal('Rincian · '+r.nama,detailHtml(r,true));
  if($('ttFull'))$('ttFull').onclick=()=>{closeModal();tmState.team=false;tmState.person=nik;reset();render();};
  if($('ttKpi'))$('ttKpi').onclick=()=>tmPersonKpi(nik);
 };
 window.tmDailyReport=async function(){
  const b=$('ttReport');if(b)b.disabled=true;
  try{const r=await rpc('apiTMDailyReport',TOKEN);
   modal('Daily Report · Format teks',`<div class="tmx-text-tools"><button class="chip primary" id="ttCopy">Salin teks untuk WhatsApp</button> <span class="hint" id="ttOk">Data real-time saat tombol ditekan · hanya form order yang sudah disimpan</span></div><pre class="tm-wa-text">${esc(r.text)}</pre>`);
   $('ttCopy').onclick=()=>{const done=()=>{$('ttCopy').textContent='Tersalin ✓';};if(navigator.clipboard?.writeText)navigator.clipboard.writeText(r.text).then(done,()=>$('ttOk').textContent='Blok teks lalu salin manual');else $('ttOk').textContent='Blok teks lalu salin manual';};
  }catch(e){typeof fail==='function'?fail(e,()=>{}):alert(e.message);}finally{if(b)b.disabled=false;}
 };
})();


/* ===== Catat FU · jadwal FU berikutnya otomatis ===== */
tmFollowUpForm=async function(dealer,brand){
 const days=Number(tmState.activity?.staleDays||tmState.boot?.profile?.stale_days||7)||7,today=tmToday();
 const plus=(d,n)=>{const t=new Date(d+'T00:00:00');t.setDate(t.getDate()+n);return t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');};
 const opts=[...new Set([3,days,14,30])].sort((a,b)=>a-b);let cur=days,auto=true;
 modal('Catat Follow Up',`<form id="tmFUForm"><div class="userForm"><label>Dealer<input class="fi" value="${esc(dealer)}" readonly></label><label>Brand<input class="fi" value="${esc(brand)}" readonly></label><label>Tanggal FU<input class="fi" type="date" name="date" value="${today}" max="${today}" required></label><label>Metode<select class="fi" name="method">${tmOptions(['WhatsApp','Telepon','Kunjungan','Lainnya'],'WhatsApp')}</select></label><label>Hasil FU<input class="fi" name="result" list="tmFUResults" placeholder="Tulis atau pilih hasil FU" maxlength="180" required><datalist id="tmFUResults">${['Berminat order','Belum membutuhkan','Tidak terhubung','Minta dihubungi kembali','Menunggu stok','Order dicatat'].map(s=>`<option>${s}</option>`).join('')}</datalist></label><label>FU berikutnya <span class="fu-auto" id="fuAuto"></span><input class="fi" type="date" name="next" id="fuNext"><div class="fu-chips" id="fuChips"></div><small class="hint" id="fuHint"></small></label></div><label>Catatan<textarea class="fi" name="note" rows="3" maxlength="4000"></textarea></label><p id="tmFUError" class="hint" role="alert"></p><button class="chip primary">Simpan FU</button></form>`);
 const form=$('tmFUForm'),next=$('fuNext');
 const draw=()=>{$('fuChips').innerHTML=opts.map(n=>`<button type="button" data-fun="${n}" class="${auto&&n===cur?'on':''}">+${n} hari</button>`).join('')+`<button type="button" data-fun="0" class="${next.value===''?'on':''}">Tanpa jadwal</button>`;
  $('fuAuto').textContent=next.value===''?'tanpa jadwal':auto?'otomatis · '+cur+' hari':'diubah manual';
  $('fuHint').textContent=next.value===''?'Dealer ini tidak punya jadwal, hanya ditandai Lama tidak FU setelah '+days+' hari.':'Jadwal FU berikutnya: '+tgl(next.value)+'.';
  $('fuChips').querySelectorAll('[data-fun]').forEach(b=>b.onclick=()=>{const n=+b.dataset.fun;if(!n){next.value='';auto=false;}else{cur=n;auto=true;next.value=plus(form.date.value||today,n);}draw();});};
 next.value=plus(today,cur);draw();
 form.date.onchange=()=>{if(auto&&next.value!==''){next.value=plus(form.date.value||today,cur);draw();}};
 next.onchange=()=>{auto=false;draw();};
 form.onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button.primary');b.disabled=true;try{await rpc('apiTMFollowUpSave',TOKEN,{...Object.fromEntries(new FormData(e.target)),dealer,brand});closeModal();await render();}catch(err){$('tmFUError').textContent=err.message;}finally{b.disabled=false;}};
};
